CREATE OR REPLACE FUNCTION foundation_onboarding_url_valid(raw text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE parts text[];hostname text;labels text[];label text;last_label text;address inet;tail text; BEGIN
