 IF parts IS NULL OR (parts[3] IS NOT NULL AND parts[3]::integer>65535) THEN RETURN false; END IF;
 hostname:=lower(parts[1]);
 IF left(hostname,1)='[' THEN
  hostname:=substr(hostname,2,length(hostname)-2); address:=hostname::inet;
  IF family(address)<>6 OR masklen(address)<>128 THEN RETURN false; END IF;
  IF position('.' IN hostname)>0 THEN
   tail:=regexp_replace(hostname,'^.*:','');labels:=string_to_array(tail,'.');
   IF cardinality(labels)<>4 THEN RETURN false; END IF;
   FOREACH label IN ARRAY labels LOOP IF label !~ '^(0|[1-9][0-9]{0,2})$' OR label::integer>255 THEN RETURN false; END IF; END LOOP;
  END IF;
  RETURN true;
 END IF;
 IF right(hostname,1)='.' THEN hostname:=left(hostname,length(hostname)-1); END IF;
 labels:=string_to_array(hostname,'.');
 IF length(hostname)>253 OR cardinality(labels)=0 THEN RETURN false; END IF;
 FOREACH label IN ARRAY labels LOOP IF label !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$' OR left(label,4)='xn--' THEN RETURN false; END IF; END LOOP;
 last_label:=labels[cardinality(labels)];
 IF last_label ~ '^([0-9]+|0x[0-9a-f]*)$' THEN
  IF cardinality(labels)<>4 THEN RETURN false; END IF;
  FOREACH label IN ARRAY labels LOOP IF label !~ '^(0|[1-9][0-9]{0,2})$' OR label::integer>255 THEN RETURN false; END IF; END LOOP;
 END IF;
 RETURN true;
 EXCEPTION WHEN OTHERS THEN RETURN false; END $$;
