CREATE OR REPLACE FUNCTION foundation_onboarding_record_valid(kind text,value jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN
