CREATE OR REPLACE FUNCTION foundation_onboarding_outcome_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE p foundation_onboarding_proposal%ROWTYPE;d foundation_onboarding_decision%ROWTYPE;r resource%ROWTYPE;l project_resource_link%ROWTYPE;c resource_identity_claim%ROWTYPE;v integer; BEGIN
 SELECT * INTO p FROM foundation_onboarding_proposal WHERE id=NEW.proposal_id FOR UPDATE;SELECT max(version) INTO v FROM foundation_onboarding_decision WHERE proposal_id=NEW.proposal_id;SELECT * INTO d FROM foundation_onboarding_decision WHERE id=NEW.decision_id;
 IF NEW.creation_transaction<>pg_current_xact_id()::text OR d.id IS NULL OR d.version<>v OR d.record->>'decision'<>'approved' OR foundation_onboarding_at_lte(d.record->>'expiresAt',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) OR NEW.record->>'decisionDigest'<>d.record->>'contentDigest' OR NEW.record->>'proposalDigest'<>p.record->>'contentDigest' OR d.record->>'expectedProposalDigest'<>p.record->>'contentDigest' OR NEW.record->'link'->>'type'<>p.record->>'relationship' THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_approval',MESSAGE='Invalid onboarding approval'; END IF;
 IF EXISTS(SELECT 1 FROM foundation_onboarding_proposal_evidence m JOIN foundation_evidence e ON e.id=m.evidence_id AND e.project_id=m.project_id WHERE m.proposal_id=NEW.proposal_id AND e.availability<>'available') THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_evidence',MESSAGE='Onboarding source unavailable'; END IF;
 SELECT * INTO r FROM resource WHERE id=NEW.resource_id FOR SHARE;SELECT * INTO l FROM project_resource_link WHERE id=NEW.link_id FOR SHARE;
 IF r.id IS NULL OR l.id IS NULL OR foundation_onboarding_resource_snapshot(r)<>NEW.record->'resource' OR l.project_id<>NEW.project_id OR l.resource_id<>NEW.resource_id OR l.type<>p.record->>'relationship' OR l.lifecycle<>'active' OR l.source_kind<>(CASE WHEN l.type='supports' THEN 'resource' ELSE 'project' END) OR l.target_kind<>(CASE WHEN l.type='supports' THEN 'project' ELSE 'resource' END) OR NEW.record->'link'<>jsonb_build_object('id',l.id,'projectId',l.project_id,'resourceId',l.resource_id,'type',l.type,'lifecycle',l.lifecycle) THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_snapshot',MESSAGE='Onboarding inventory changed'; END IF;
 IF (NEW.record->>'linkCreated')::boolean<>(d.record->'preconditions'->'link'='null'::jsonb) OR ((NEW.record->>'linkCreated')::boolean AND (l.provenance<>'foundation-onboarding' OR l.created_at<>(NEW.record->>'recordedAt')::timestamptz)) OR (NOT (NEW.record->>'linkCreated')::boolean AND NEW.record->'link'<>d.record->'preconditions'->'link') THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_link',MESSAGE='Invalid onboarding connection'; END IF;
 IF p.record->'target'->>'mode'='create' THEN
  SELECT * INTO c FROM resource_identity_claim WHERE resource_id=r.id;
  IF NEW.record->'resourceCreated'<>'true'::jsonb OR NEW.record->'identity'<>p.record->'target'->'identity' OR c.resource_id IS NULL OR c.creation_transaction<>pg_current_xact_id()::text OR c.namespace<>NEW.record->'identity'->>'namespace' OR c.authority<>NEW.record->'identity'->>'authority' OR c.external_id<>NEW.record->'identity'->>'externalId' OR c.recorded_by<>NEW.record->>'recordedBy' OR c.recorded_at<>NEW.record->>'recordedAt' OR r.name<>p.record->'target'->>'name' OR to_jsonb(r.subtype) IS DISTINCT FROM nullif(p.record->'target'->'subtype','null'::jsonb) OR to_jsonb(r.external_url) IS DISTINCT FROM nullif(p.record->'target'->'externalUrl','null'::jsonb) OR r.parent_resource_id IS NOT NULL OR r.state IS NOT NULL OR r.last_observed_at IS NOT NULL OR r.created_at<>(NEW.record->>'recordedAt')::timestamptz OR d.record->'preconditions'<>jsonb_build_object('resource',NULL,'link',NULL,'identityResourceId',NULL) THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_identity',MESSAGE='Invalid onboarding identity'; END IF;
 ELSE IF NEW.record->'resourceCreated'<>'false'::jsonb OR NEW.record->'identity'<>'null'::jsonb OR NEW.resource_id::text<>p.record->'target'->>'resourceId' OR NEW.record->'resource'<>d.record->'preconditions'->'resource' THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_reuse',MESSAGE='Invalid onboarding reuse'; END IF; END IF;
 IF foundation_onboarding_at_lte(d.record->>'expiresAt',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='foundation_onboarding_outcome_deadline',MESSAGE='Onboarding approval expired'; END IF;RETURN NULL;END $$;
