DO $$ DECLARE target_role record;privilege text;table_name text; BEGIN FOR target_role IN SELECT r.rolname FROM pg_roles r WHERE NOT r.rolsuper AND r.rolname<>current_user AND r.rolname<>(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid='public.resource'::regclass) LOOP FOREACH privilege IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE'] LOOP IF has_table_privilege(target_role.rolname,'public.resource',privilege) AND has_table_privilege(target_role.rolname,'public.project_resource_link',privilege) THEN FOREACH table_name IN ARRAY ARRAY['resource_identity_claim','foundation_onboarding_proposal','foundation_onboarding_proposal_evidence','foundation_onboarding_decision','foundation_onboarding_outcome'] LOOP EXECUTE format('GRANT %s ON TABLE public.%I TO %I',privilege,table_name,target_role.rolname); END LOOP; END IF; END LOOP; END LOOP; END $$;
